CREATE SCHEMA IF NOT EXISTS industrendindia AUTHORIZATION CURRENT_USER; SET search_path TO industrendindia,pg_catalog;
CREATE TABLE IF NOT EXISTS notification_deliveries(notification_id uuid PRIMARY KEY,customer_id uuid,channel varchar(20) NOT NULL,template_key varchar(120) NOT NULL,destination varchar(254) NOT NULL,provider varchar(40),provider_message_id varchar(180),status varchar(20) NOT NULL,error_code varchar(80),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),delivered_at timestamptz); CREATE INDEX IF NOT EXISTS notification_destination_idx ON notification_deliveries(destination,created_at DESC);
